        { q: 'Por que Acabe odiava Micaías?', o: ['Ele nunca profetizava coisas boas para Acabe', 'Era estrangeiro', 'Era rico', 'Cantava mal'], e: '1 Reis 22:8.' },
        { q: 'Como Micaías viu Israel na visão?', o: ['Como ovelhas sem pastor', 'Como leões', 'Como um exército vencedor', 'Como pássaros'], e: '1 Reis 22:17.' },
        { q: 'Como Acabe tentou escapar?', o: ['Indo disfarçado', 'Ficando em casa', 'Fugindo para o Egito', 'Orando'], e: '1 Reis 22:30.' }
