        { q: 'O que o servo viu no monte?', o: [['🔥', 'Cavalos e carros de fogo'], ['🐑', 'Ovelhas'], ['🌳', 'Só árvores']] },
        { q: 'O que Eliseu deu aos inimigos?', o: [['🍞', 'Um banquete'], ['⚔️', 'Uma surra'], ['⛓️', 'Correntes']] }
